import java.util.Scanner;

public class Main {
    static int pogona(String nom) {
        switch (nom) {
            case "RS-232": case "DSL": return 1;
            case "Ethernet": case "WiFi": case "PPP": return 2;
            case "IP": case "ICMP": case "OSPF": return 3;
            case "TCP": case "UDP": return 4;
            case "NetBIOS": case "RPC": return 5;
            case "TLS": case "JPEG": case "UTF-8": return 6;
            case "HTTP": case "FTP": case "SMTP": case "DNS": return 7;
            default: return 0;
        }
    }

    static String birlik(String nom) {
        int p = pogona(nom);
        if (p == 1) return "bit";
        if (p == 2) return "frame";
        if (p == 3) return "packet";
        if (p == 4) {
            if (nom.equals("TCP")) return "segment";
            return "datagram";
        }
        if (p == 0) return "unknown";
        return "message";
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int k = in.nextInt();
        for (int i = 0; i < k; i++) {
            String nom = in.next();
            System.out.println(nom + " " + pogona(nom) + " " + birlik(nom));
        }
    }
}

