#include <iostream>
#include <string>
using namespace std;

int pogona(const string& nom) {
    if (nom == "RS-232" || nom == "DSL") return 1;
    if (nom == "Ethernet" || nom == "WiFi" || nom == "PPP") return 2;
    if (nom == "IP" || nom == "ICMP" || nom == "OSPF") return 3;
    if (nom == "TCP" || nom == "UDP") return 4;
    if (nom == "NetBIOS" || nom == "RPC") return 5;
    if (nom == "TLS" || nom == "JPEG" || nom == "UTF-8") return 6;
    if (nom == "HTTP" || nom == "FTP" || nom == "SMTP" || nom == "DNS") return 7;
    return 0;
}

string birlik(const string& nom) {
    int p = pogona(nom);
    if (p == 1) return "bit";
    if (p == 2) return "frame";
    if (p == 3) return "packet";
    if (p == 4) {
        if (nom == "TCP") return "segment";
        return "datagram";
    }
    if (p == 0) return "unknown";
    return "message";
}

int main() {
    int k;
    cin >> k;
    for (int i = 0; i < k; i++) {
        string nom;
        cin >> nom;
        cout << nom << " " << pogona(nom) << " " << birlik(nom) << endl;
    }
    return 0;
}
